+int drm_user_fence_set_compare(struct drm_user_fence *ufence,
+			       u64 __user *addr, u64 value,
+			       enum drm_user_fence_cmp op)
+{
+	/*
+	 * get_user() of u64 is not atomic on 32-bit — caller should not
+	 * reach here on non-64-bit kernels.
